  (24, 'Riley', 'nonbinary', '{woman,man,nonbinary}', 29, 'Photographer', 'Prospect Heights', '11238', 'Brooklyn', 'https://d8j0ntlcm91z4.cloudfront.net/user_3JGuIsmzGLwAlDRE1EVJShdEdvJ/hf_20261107_164843_b444ecf7-2d83-4734-b0fb-63f3d8b91101.png', '[{"q": "Two truths and a lie…", "a": "I’ve met the Pope, I can juggle, I’ve never been to Jersey."}, {"q": "My most irrational splurge…", "a": "A $40 olive oil. It changed my life, though."}, {"q": "My perfect NYC Saturday…", "a": "Farmers market, cook all afternoon, dinner party."}]'::jsonb, '[{"slot": "favorite", "name": "Joe’s Pizza", "note": "My go-to on a Tuesday."}, {"slot": "date", "name": "Bar Pisellino", "note": "Dim lights, great martinis."}, {"slot": "weekend", "name": "Brooklyn Bridge Park", "note": "Rain or shine."}]'::jsonb, '{"Saver","Debt: strategic","Whoever asked pays","Joint finances","Owning in 3 yrs","Real estate"}'::text[], '0GjEhVFGZW8afUYGChu3Rr', 'Dancing Queen', 'ABBA', 'https://i.scdn.co/image/ab67616d00001e0270f7a1b35d5165c85b95a0e0', 178, 'no', 'open', 'bachelors', 'socially', 'never', 'often', 'relationship', 'want', 'christian', 'liberal', 'I pay my card off in full every month', 'concert tickets', 'subscriptions', 'strong', 'up', true, 'membership', false, 'riley.nyc'),
  (25, 'Jordan', 'nonbinary', '{woman,man,nonbinary}', 32, 'UX researcher', 'Chelsea', '10001', 'Manhattan', 'https://d8j0ntlcm91z4.cloudfront.net/user_3JGuIsmzGLwAlDRE1EVJShdEdvJ/hf_20261107_164842_0844e8a6-0a08-4ea7-b3d5-839f9e71838d.png', '[{"q": "Best purchase I ever made…", "a": "Good knives. I cook almost every night."}, {"q": "My ideal Sunday costs about…", "a": "$0 if you count Prospect Park and good company."}, {"q": "A green flag I look for…", "a": "Close with their friends."}]'::jsonb, '[{"slot": "favorite", "name": "Katz’s Delicatessen", "note": "Order the cacio e pepe."}, {"slot": "date", "name": "Attaboy", "note": "Order whatever they recommend."}, {"slot": "weekend", "name": "The High Line", "note": "Bring a book."}]'::jsonb, '{"Balanced","Debt: strategic","Splits the check","A bit of both","Retire early","Index funds"}'::text[], '69kOkLUCkxIZYexIgSG8rq', 'Get Lucky', 'Daft Punk', 'https://i.scdn.co/image/ab67616d00001e029b9b36b0e22870b9f542d937', 168, 'no', 'yes', 'masters', 'socially', 'never', 'sometimes', 'figuring_out', 'both', 'hindu', 'moderate', 'I have a spreadsheet for everything', 'travel', 'cable', 'elite', 'steady', false, 'premium', false, null::text)
) as t(n, first, g, seek, age, job, hood, zip, boro, photo, prompts, nyc, mv, sid, stitle, sartist, simg, height, has_kids, wants_kids, edu,
         drinking, smoking, exercise, looking, pets, religion, politics, habit, splurge, save, band, trend, improving, plan, founder, insta)
loop
  em := lower(r.first) || '.t' || r.n || '@seed.scoredate.test';
  continue when exists (select 1 from auth.users u where u.email = em);
  uid := gen_random_uuid();
  insert into auth.users(instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, created_at, updated_at,
                         raw_app_meta_data, raw_user_meta_data, is_sso_user, is_anonymous,
                         confirmation_token, recovery_token, email_change_token_new, email_change_token_current, email_change,
                         reauthentication_token, phone_change, phone_change_token)
  values ('00000000-0000-0000-0000-000000000000', uid, 'authenticated', 'authenticated', em,
          crypt('ScoreDemo!2026', gen_salt('bf')), now(), now() - make_interval(days => r.n), now(),
          '{"provider":"email","providers":["email"]}', jsonb_build_object('demo', true), false, false,
          '', '', '', '', '', '', '', '');
  insert into auth.identities(id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  values (gen_random_uuid(), uid, uid::text, jsonb_build_object('sub', uid::text, 'email', em, 'email_verified', true), 'email', now(), now(), now());

  update profiles set
    first_name = r.first, gender = r.g, seeking = r.seek::text[],
    birth_year = extract(year from now())::int - r.age,
    job = r.job, neighborhood = r.hood, zip = r.zip, borough = r.boro, city = 'New York',
    prompts = r.prompts, prompt_q = r.prompts->0->>'q', prompt_a = r.prompts->0->>'a',
    my_nyc = r.nyc, money_values = r.mv,
    song_id = r.sid, song_title = r.stitle, song_artist = r.sartist, song_image = r.simg,
    height_cm = r.height, has_kids = r.has_kids, wants_kids = r.wants_kids, education = r.edu,
    drinking = r.drinking, smoking = r.smoking, exercise = r.exercise,
    looking_for = r.looking, pets = r.pets, religion = r.religion, politics = r.politics,
    flag_habit = r.habit, flag_splurge = r.splurge, flag_save = r.save,
    band = r.band, trend = r.trend, show_improving = r.improving, show_verified = true,
    credit_verified_at = now() - make_interval(days => 3 + r.n * 2),
    id_status = 'approved', photo_status = 'approved',
    plan = r.plan, status = case when r.plan = 'preview' then 'preview' else 'active' end,
    preview_ends_at = case when r.plan = 'preview' then now() + interval '5 days' end,
    is_founder = r.founder,
    last_active_at = now() - make_interval(mins => (r.n * 37) % 600),
    created_at = now() - make_interval(days => r.n)
  where id = uid;

  insert into photos(user_id, path, position, match_status, match_similarity) values (uid, r.photo, 0, 'approved', 99);
  if r.insta is not null then
    insert into profile_socials(user_id, instagram, instagram_public) values (uid, r.insta, true) on conflict (user_id) do nothing;
  end if;
  made := made + 1;
end loop;
raise notice 'Created % test members', made;
end $$;

-- Check: should list 25 people
select p.first_name, u.email, p.band, p.plan, p.neighborhood, p.song_title || ' · ' || p.song_artist as song
from auth.users u join profiles p on p.id = u.id where u.email like '%.t%@seed.scoredate.test' order by u.created_at desc;
